const $=s=>document.querySelector(s),state={csrf:null,role:null,branch:null,page:'appointments',schedules:[],contact:null,payment:null,recordInfo:null,rx:null,issue:null,plans:null,planAction:null,quoteIssue:null,decision:null,rxAction:null,stock:null,purchaseData:null,purchaseAction:null,dayclose:null,patientKey:null,scheduleData:null,visitTime:null,treatmentData:null,resourceAction:null,followups:null,assessment:null,transferData:null,transferAction:null,approvalData:null,approvalAction:null};
const pages={appointments:['预约接诊','查看本店预约与排班',['frontdesk']],transfers:['跨店预约交接','由两店前台核对并衔接预约',['frontdesk']],approvals:['跨店病历授权','由门店负责人核对授权',['manager']],crossclinical:['授权病历查阅','查看本人获授权的跨店资料',['dentist']],patients:['患者档案','维护连锁共享的患者身份信息',['frontdesk']],schedules:['门店排班','安排本店医生与诊椅',['manager']],followups:['复诊跟进','查看需要联系和跟进的患者',['frontdesk','dentist','manager']],record:['病历与健康复核','查看和填写本人本店负责的就诊',['dentist']],prescription:['院外处方','管理本人本店接诊的处方',['dentist']],treatment:['实际诊疗','记录本人实际操作与费用依据',['dentist']],plans:['治疗方案','管理本人本店接诊方案',['dentist']],quotes:['报价单','查看本店治疗报价',['dentist','cashier']],finance:['费用查询','按患者核对本店账目',['cashier']],feeRequests:['费用更正与退费','核对原账单并记录系统外退款',['cashier','manager']],prices:['门店价目','查看本店收费项目与价目',['cashier','manager']],inventory:['材料库存','查看本店材料批次与库存',['assistant']],purchases:['采购验收','办理本店采购与到货验收',['assistant','manager']],dayclose:['日终对账','核对本店实际收退款',['manager']],resources:['诊椅资源','查看本店诊椅使用情况',['manager','assistant','dentist']]};
function notify(message,error=false){const el=$('#message');el.textContent=message;el.className='message'+(error?' error':'');el.hidden=false;}
function dialogError(form,message){const el=form.querySelector('.dialog-error');el.textContent=message;el.hidden=!message;}
async function api(url,data){const role=state.role,branch=state.branch;const response=await fetch(url,{method:data?'POST':'GET',headers:{'Content-Type':'application/json',...(role?{'X-Clinic-Role':role}:{}),...(state.csrf?{'X-CSRF-Token':state.csrf}:{})},...(data?{body:JSON.stringify(data)}:{})});const value=await response.json();if(role&&(role!==state.role||branch!==state.branch))throw Error('岗位或门店已切换，请重新操作');if(!response.ok)throw Error(value.message||'请求失败');return value;}
function option(select,value,label){const el=document.createElement('option');el.value=value;el.textContent=label;select.append(el);}
function table(node,columns,rows){node.replaceChildren();if(!rows.length){const p=document.createElement('p');p.className='empty';p.textContent='暂无记录';node.append(p);return;}const t=document.createElement('table'),head=document.createElement('thead'),hr=document.createElement('tr');for(const [label] of columns){const th=document.createElement('th');th.textContent=label;hr.append(th);}head.append(hr);t.append(head);const body=document.createElement('tbody');for(const row of rows){const tr=document.createElement('tr');for(const [,get] of columns){const td=document.createElement('td'),value=get(row);if(value instanceof Node)td.append(value);else td.textContent=value??'—';tr.append(td);}body.append(tr);}t.append(body);node.append(t);}
function showPage(page){state.page=page;for(const el of document.querySelectorAll('.page'))el.hidden=el.id!==page;for(const b of document.querySelectorAll('#nav button'))b.classList.toggle('active',b.dataset.page===page);$('#title').textContent=pages[page][0];$('#subtitle').textContent=pages[page][1];$('#message').hidden=true;load().catch(e=>notify(e.message,true));}
function localTime(value){const d=new Date(value),p=n=>String(n).padStart(2,'0');return d.getFullYear()+'-'+p(d.getMonth()+1)+'-'+p(d.getDate())+'T'+p(d.getHours())+':'+p(d.getMinutes());}function localTimeSeconds(value){const d=new Date(value),p=n=>String(n).padStart(2,'0');return localTime(value)+':'+p(d.getSeconds());}function key(){return crypto.randomUUID();}function time(value){return value?new Date(value).toLocaleString('zh-CN',{hour12:false}):'—';}function q(params){return new URLSearchParams(params).toString();}
async function load(){if(!state.branch){notify('当前岗位没有可用门店，请联系负责人。',true);return;}const branchId=state.branch;
 if(state.page==='appointments'){const data=await api('/api/reception/options?'+q({branchId}));if(branchId!==state.branch)return;state.schedules=data.schedules;const p=$('#appointment-form [name=patientId]'),s=$('#appointment-form [name=scheduleId]');p.replaceChildren();s.replaceChildren();for(const x of data.patients)option(p,x.id,x.name+' · '+x.record_no);for(const x of data.schedules)option(s,x.id,x.dentist_name+' / '+x.chair_name+' / '+time(x.starts_at));table($('#appointment-list'),[['预约编号',x=>x.id],['患者',x=>x.patient_name],['编号',x=>x.patient_no],['预约时间',x=>time(x.planned_start)],['状态',x=>x.status],['操作',x=>{if(x.status!=='已预约')return '—';const box=document.createElement('div'),arrive=document.createElement('button'),cancel=document.createElement('button');arrive.className=cancel.className='secondary';arrive.textContent='登记到诊';arrive.onclick=()=>openVisitTime('arrive',x,branchId);cancel.textContent='取消预约';cancel.onclick=async()=>{const reason=window.prompt('请输入取消原因');if(!reason?.trim())return;try{await api('/api/reception',{action:'cancel',branchId,appointmentId:x.id,expectedRevision:x.revision,reason:reason.trim(),requestKey:key(),commandVersion:1});notify('预约已取消');await load();}catch(e){notify(e.message,true);}};box.append(arrive,cancel);return box;}]],data.appointments);}
 else if(state.page==='transfers'){await loadTransfers();}
 else if(state.page==='approvals'){await loadApprovals();}
 else if(state.page==='crossclinical'){await loadCrossClinical();}
 else if(state.page==='patients'){await loadPatients();}
 else if(state.page==='schedules'){await loadSchedules();}
 else if(state.page==='record'){await loadDoctorVisits();}
 else if(state.page==='treatment'){await loadTreatment();}
 else if(state.page==='followups'){await loadFollowups();}
 else if(state.page==='quotes'){await queryQuotes();}
 else if(state.page==='purchases'){await queryPurchases();}
 else if(state.page==='dayclose'){await queryDayClose();}
 else if(state.page==='feeRequests'){await loadFeeRequests();}
 else if(state.page==='prices'){const d=await api('/api/prices?'+q({branchId}));table($('#price-list'),[['项目',x=>d.services.find(s=>s.id===x.service_id)?.name||x.service_id],['金额',x=>'¥ '+(x.unit_price_cents/100).toFixed(2)],['生效时间',x=>time(x.valid_from)],['状态',x=>x.status]],d.prices);}
 else if(state.page==='inventory'){const d=await api('/api/inventory?'+q({branchId}));table($('#inventory-list'),[['材料',x=>x.materialName],['批次',x=>x.batchNo],['库存',x=>displayQuantity(x.quantityScaled,x.scale)+' '+x.unit],['位置',x=>x.locationName],['批次状态',x=>x.batchStatus],['操作',x=>{if(!x.available)return '—';const button=document.createElement('button');button.className='secondary';button.textContent='登记领用';button.onclick=()=>{state.stock={item:x,branchId,requestKey:key()};const f=$('#stock-form');f.reset();dialogError(f,'');$('#stock-summary').textContent=x.materialName+' / '+x.batchNo+' / 可用 '+displayQuantity(x.quantityScaled,x.scale)+' '+x.unit;$('#stock-dialog').showModal();};return button;}]],d.items);}
 else if(state.page==='resources'){const d=await api('/api/resources?'+q({branchId}));table($('#resource-list'),[['诊椅',x=>x.name],['状态',x=>x.busy?'使用中':d.blocks.some(b=>b.dental_chair_id===x.id)?'清洁或维护中':'可用']],d.chairs);table($('#resource-blocks'),[['资源',x=>x.chair_name||x.equipment_name],['原因',x=>x.reason],['开始时间',x=>time(x.starts_at)],['操作',x=>{if(!['assistant','manager'].includes(state.role))return '—';if(state.role==='assistant'&&x.reason.startsWith('故障维护：'))return '需负责人核实';const button=document.createElement('button');button.className='secondary';button.textContent='核实恢复';button.onclick=()=>openResourceAction('restore',x,branchId);return button;}]],d.blocks);}}
function clearSensitive(){for(const selector of ['#record-result','#finance-result','#appointment-list','#followup-list','#price-list','#inventory-list','#resource-list'])$(selector).replaceChildren();for(const dialog of document.querySelectorAll('dialog[open]'))dialog.close();state.contact=null;state.payment=null;state.recordInfo=null;state.rx=null;state.issue=null;state.plans=null;state.planAction=null;state.quoteIssue=null;state.decision=null;state.rxAction=null;state.stock=null;state.purchaseData=null;state.purchaseAction=null;state.dayclose=null;state.patientKey=null;state.scheduleData=null;state.visitTime=null;state.treatmentData=null;state.resourceAction=null;state.followups=null;state.assessment=null;state.transferData=null;state.transferAction=null;state.approvalData=null;state.approvalAction=null;for(const id of ['#transfer-list','#approval-list','#grant-list','#crossclinical-list','#crossclinical-result','#fee-sources','#fee-requests-list'])$(id).replaceChildren();$('#followup-create-panel').hidden=true;$('#treatment-visits').replaceChildren();$('#treatment-form').reset();$('#resource-blocks').replaceChildren();$('#patient-list').replaceChildren();$('#schedule-list').replaceChildren();$('#doctor-visits').replaceChildren();$('#purchase-list').replaceChildren();$('#purchase-create').hidden=true;$('#dayclose-form').hidden=true;$('#dayclose-list').replaceChildren();$('#dayclose-summary').textContent='';$('#plan-list').replaceChildren();$('#plan-draft').hidden=true;$('#quote-list').replaceChildren();$('#health-panel').hidden=true;$('#prescription-list').replaceChildren();$('#prescription-draft').hidden=true;$('#prescription-empty').hidden=true;}
async function branches(){clearSensitive();const d=await api('/api/branches'),select=$('#branch');select.replaceChildren();for(const b of d.items)option(select,b.id,b.name);state.branch=d.items[0]?.id??null;const available=Object.keys(pages).filter(p=>pages[p][2].includes(state.role));for(const b of document.querySelectorAll('#nav button'))b.hidden=!available.includes(b.dataset.page);if(available.length)showPage(available[0]);}
$('#login-form').onsubmit=async e=>{e.preventDefault();const f=e.currentTarget;try{const d=await api('/api/login',{username:f.username.value,password:f.password.value});state.csrf=d.csrf;f.password.value='';$('#user').textContent=d.user.name;const roles=$('#role');roles.replaceChildren();for(const role of d.user.roles)if(Object.values(pages).some(p=>p[2].includes(role.code)))option(roles,role.code,role.name);state.role=roles.value;$('#login-view').hidden=true;$('#app').hidden=false;await branches();}catch(error){alert(error.message);}};
$('#role').onchange=async e=>{state.role=e.target.value;try{await branches();}catch(error){notify(error.message,true);}};$('#branch').onchange=e=>{state.branch=Number(e.target.value);clearSensitive();load().catch(error=>notify(error.message,true));};$('#nav').onclick=e=>{const b=e.target.closest('button[data-page]');if(b)showPage(b.dataset.page);};$('#refresh').onclick=()=>load().catch(e=>notify(e.message,true));$('#logout').onclick=async()=>{try{await api('/api/logout',{});location.reload();}catch(e){notify(e.message,true);}};
$('#appointment-form').onsubmit=async e=>{e.preventDefault();const f=e.currentTarget,s=state.schedules.find(x=>x.id===Number(f.scheduleId.value));if(!s){notify('请先选择有效排班',true);return;}try{await api('/api/reception',{action:'create',branchId:state.branch,patientId:Number(f.patientId.value),scheduleId:s.id,scheduleRevision:s.revision,startsAt:new Date(f.startsAt.value).toISOString().replace('.000Z','Z'),endsAt:new Date(f.endsAt.value).toISOString().replace('.000Z','Z'),reason:f.reason.value,requestKey:key(),commandVersion:1});f.reason.value='';await load();notify('预约已保存');}catch(error){notify(error.message,true);}};
$('#record-form').onsubmit=async e=>{e.preventDefault();const branchId=state.branch,visitId=Number(e.currentTarget.visitId.value);try{const d=await api('/api/record/draft?'+q({branchId,visitId})),health=await api('/api/record/health?'+q({branchId,visitId})),el=$('#record-result'),form=document.createElement('form');state.recordInfo={branchId,visitId,record:d.record,health};form.className='editor';const fields=[['chiefComplaint','主诉',d.record.chief_complaint],['diagnosis','诊断',d.record.diagnosis],['treatmentAdvice','诊疗建议',d.record.treatment_advice]];for(const [name,label,value] of fields){const wrap=document.createElement('label'),area=document.createElement('textarea');wrap.textContent=label;area.name=name;area.value=value||'';area.maxLength=4000;area.readOnly=d.record.status!=='草稿';wrap.append(area);form.append(wrap);}for(const finding of d.findings){const p=document.createElement('p');p.className='hint';p.textContent='已有检查所见：'+finding.finding_text;form.append(p);}if(d.record.status==='草稿'){const wrap=document.createElement('label'),area=document.createElement('textarea');wrap.textContent='新增检查所见（可选）';area.name='newFinding';area.maxLength=4000;wrap.append(area);form.append(wrap);}const info=document.createElement('p');info.className='hint';info.textContent='病历状态：'+d.record.status+'。现有检查所见会保留。';form.append(info);if(d.record.status==='草稿'){const button=document.createElement('button');button.textContent='保存病历草稿';form.append(button);const requestKey=key();form.onsubmit=async event=>{event.preventDefault();button.disabled=true;try{const findings=d.findings.map(x=>({id:x.id,toothCode:x.tooth_code,surfaceCode:x.surface_code,text:x.finding_text}));if(form.elements.newFinding.value.trim())findings.push({text:form.elements.newFinding.value.trim()});await api('/api/record/draft',{branchId,visitId,recordId:d.record.id,expectedRevision:d.record.revision,chiefComplaint:form.elements.chiefComplaint.value,diagnosis:form.elements.diagnosis.value,treatmentAdvice:form.elements.treatmentAdvice.value,findings,requestKey,commandVersion:1});notify('病历草稿已保存，请重新查询后继续修改');button.disabled=true;}catch(error){notify(error.message,true);button.disabled=false;}};}el.replaceChildren(form);renderHealth(health,d.record.status);}catch(error){notify(error.message,true);}};
async function queryFinance(patientId){const branchId=state.branch,d=await api('/api/finance?'+q({branchId,patientId}));table($('#finance-result'),[['账单编号',x=>x.record_no],['应收',x=>'¥ '+(x.summary.receivableCents/100).toFixed(2)],['待付',x=>'¥ '+(x.summary.unpaidCents/100).toFixed(2)],['操作',x=>{if(x.summary.unpaidCents<=0||x.summary.pendingPricingCount)return '—';const b=document.createElement('button');b.className='secondary';b.textContent='登记收款';b.onclick=async()=>{try{const clock=await api('/api/status');state.payment={bill:x,patientId,branchId,requestKey:key()};const form=$('#payment-form');form.reset();dialogError(form,'');form.elements.receivedAt.value=localTime(clock.businessTime);$('#payment-bill').textContent=x.record_no+' · 待付 ¥ '+(x.summary.unpaidCents/100).toFixed(2);$('#payment-dialog').showModal();}catch(error){notify(error.message,true);}};return b;}]],d.items);}
$('#finance-form').onsubmit=async e=>{e.preventDefault();try{await queryFinance(Number(e.currentTarget.patientId.value));}catch(error){notify(error.message,true);}};
for(const button of document.querySelectorAll('[data-close]'))button.onclick=()=>document.getElementById(button.dataset.close).close();
$('#contact-form').onsubmit=async e=>{e.preventDefault();const f=e.currentTarget,entry=state.contact;if(!entry)return;const button=f.querySelector('[type=submit]');button.disabled=true;dialogError(f,'');try{if(entry.timeInput&&entry.timeInput!==f.elements.contactedAt.value)throw Error('时间已修改，请关闭窗口重新查询后办理');entry.timeInput=f.elements.contactedAt.value;if(!entry.contactedAt)entry.contactedAt=new Date(entry.timeInput).toISOString().replace('.000Z','Z');const nextStep=f.elements.nextStep.value,appointment=entry.appointments.find(x=>x.id===Number(f.elements.appointment.value));if(nextStep==='arrange'&&!appointment)throw Error('请选择本店该患者的有效预约');await api('/api/followups',{action:'contact',branchId:entry.branchId,followupId:entry.item.id,expectedRevision:entry.item.revision,method:f.elements.method.value,result:f.elements.result.value,nextStep,...(nextStep==='continue'?{nextContactDate:f.elements.nextContactDate.value}:nextStep==='arrange'?{appointmentId:appointment.id,expectedAppointmentRevision:appointment.revision}:{goalAchieved:f.elements.goalAchieved.checked,completionBasis:f.elements.completionBasis.value}),note:f.elements.note.value,contactedAt:entry.contactedAt,requestKey:entry.requestKey,commandVersion:1});$('#contact-dialog').close();state.contact=null;await load();notify('复诊联系已记录');}catch(error){dialogError(f,error.message);}finally{button.disabled=false;}};
$('#payment-form').onsubmit=async e=>{e.preventDefault();const f=e.currentTarget,entry=state.payment;if(!entry)return;dialogError(f,'');const button=f.querySelector('[type=submit]'),amount=f.elements.amount.value;if(!/^\d+(?:\.\d{1,2})?$/.test(amount)){dialogError(f,'请输入最多两位小数的金额');return;}const parts=amount.split('.'),amountCents=Number(parts[0])*100+Number((parts[1]||'').padEnd(2,'0'));if(!Number.isSafeInteger(amountCents)||amountCents<=0){dialogError(f,'金额无效');return;}button.disabled=true;try{if(entry.timeInput&&entry.timeInput!==f.elements.receivedAt.value)throw Error('时间已修改，请关闭窗口重新查询后办理');entry.timeInput=f.elements.receivedAt.value;if(!entry.receivedAt)entry.receivedAt=new Date(entry.timeInput).toISOString().replace('.000Z','Z');const channel=f.elements.channel.value;await api('/api/finance/payment',{branchId:entry.branchId,patientId:entry.patientId,billId:entry.bill.id,expectedBillRevision:entry.bill.revision,expectedFundsRevision:entry.bill.fundsRevision,amountCents,verified:f.elements.verified.checked,channel,...(channel==='现金'?{}:{externalReference:f.elements.reference.value}),evidence:f.elements.evidence.value,receivedAt:entry.receivedAt,requestKey:entry.requestKey,commandVersion:1});$('#payment-dialog').close();state.payment=null;await queryFinance(entry.patientId);notify('收款已登记');}catch(error){dialogError(f,error.message);}finally{button.disabled=false;}};
function renderHealth(health,status){const panel=$('#health-panel'),history=$('#health-history'),fields=$('#health-fields');panel.hidden=false;history.replaceChildren();fields.replaceChildren();for(const item of health.items){const p=document.createElement('p');p.className='hint';p.textContent=item.category+'：'+item.certainty+'；'+item.content+'；来源：'+item.source;history.append(p);}if(!health.items.length){const p=document.createElement('p');p.className='hint';p.textContent='暂无健康资料，请按实际核对后填写。';history.append(p);}for(const category of ['病史','过敏','用药']){const box=document.createElement('div'),label=document.createElement('label'),select=document.createElement('select'),contentLabel=document.createElement('label'),content=document.createElement('textarea');box.className='health-row';label.textContent=category+'情况';select.name=category+'-certainty';select.required=true;option(select,'','请选择');for(const choice of ['有','无','未知'])option(select,choice,choice);label.append(select);contentLabel.textContent=category+'具体内容';content.name=category+'-content';content.required=true;content.maxLength=2000;contentLabel.append(content);box.append(label,contentLabel);fields.append(box);}$('#health-form').hidden=status!=='草稿';$('#sign-form').hidden=status!=='草稿';$('#health-form').reset();$('#sign-form').reset();}
$('#health-form').onsubmit=async e=>{e.preventDefault();const f=e.currentTarget,entry=state.recordInfo;if(!entry)return;const button=f.querySelector('button');button.disabled=true;try{const now=(await api('/api/status')).businessTime,items=['病史','过敏','用药'].map(category=>({category,certainty:f.elements[category+'-certainty'].value,content:f.elements[category+'-content'].value,source:f.elements.source.value,reportedAt:now}));await api('/api/record/health',{action:'health',branchId:entry.branchId,visitId:entry.visitId,expectedHealthVersionId:entry.health.version?.id??null,items,conclusion:f.elements.conclusion.value,reason:f.elements.reason.value,requestKey:key(),commandVersion:1});$('#record-form').requestSubmit();notify('健康资料复核已保存');}catch(error){notify(error.message,true);}finally{button.disabled=false;}};
$('#sign-form').onsubmit=async e=>{e.preventDefault();const f=e.currentTarget,entry=state.recordInfo;if(!entry)return;const button=f.querySelector('button');button.disabled=true;try{await api('/api/record/health',{action:'sign',branchId:entry.branchId,visitId:entry.visitId,recordId:entry.record.id,expectedRevision:entry.record.revision,confirmed:f.elements.confirmed.checked,requestKey:key(),commandVersion:1});$('#record-form').requestSubmit();notify('病历已签署');}catch(error){notify(error.message,true);}finally{button.disabled=false;}};
async function queryPrescription(visitId,patientId){const branchId=state.branch,d=await api('/api/prescriptions?'+q({branchId,visitId,patientId}));state.rx={...d,branchId,visitId,patientId,requestKey:key()};table($('#prescription-list'),[['处方编号',p=>p.record_no],['诊断',p=>p.diagnosis],['状态',p=>p.status],['药品',p=>p.items.map(i=>i.drug_name+' × '+i.quantity_scaled/(10**i.quantity_scale)+' '+i.unit).join('；')],['操作',p=>{if(!p.canManage)return '—';const box=document.createElement('div');if(p.status==='草稿'){const b=document.createElement('button');b.className='secondary';b.textContent='开立处方';b.onclick=()=>{state.issue={rx:state.rx,prescription:p,requestKey:key()};const f=$('#issue-form');f.reset();dialogError(f,'');$('#issue-summary').textContent=p.record_no+' · '+p.diagnosis;$('#issue-dialog').showModal();};box.append(b);}if(p.status==='已开立'){for(const [action,label] of [['handover','记录处方交付'],['void','作废处方']]){if(action==='handover'&&p.handed_over_at)continue;const b=document.createElement('button');b.className='secondary';b.textContent=label;b.onclick=async()=>{try{const clock=await api('/api/status');state.rxAction={rx:state.rx,prescription:p,action,requestKey:key()};const f=$('#rx-action-form');f.reset();dialogError(f,'');$('#rx-action-title').textContent=label;$('#rx-time-label').hidden=action!=='handover';f.elements.handedAt.required=action==='handover';f.elements.handedAt.value=localTime(clock.businessTime);$('#rx-confirm-label').textContent=action==='handover'?'已核对接收人并实际交付处方文件与用药指导':'已核实药品尚未交付，确认保留原处方记录';$('#rx-action-dialog').showModal();}catch(error){notify(error.message,true);}};box.append(b);}}return box.childNodes.length?box:'—';}]],d.prescriptions);const form=$('#prescription-draft'),container=$('#rx-items');resetItemRows(container);const select=container.querySelector('[name=drug]');select.replaceChildren();for(const drug of d.drugs)option(select,drug.id,drug.name+' / '+drug.specification+' / '+drug.base_unit);form.hidden=!d.drugs.length||d.visit.status!=='接诊中';$('#prescription-empty').hidden=!!d.drugs.length;form.elements.diagnosis.value=d.record.diagnosis||'';}
$('#prescription-query').onsubmit=async e=>{e.preventDefault();state.rx=null;try{await queryPrescription(Number(e.currentTarget.visitId.value),Number(e.currentTarget.patientId.value));}catch(error){notify(error.message,true);}};
$('#prescription-draft').onsubmit=async e=>{e.preventDefault();const f=e.currentTarget,rx=state.rx;if(!rx)return;const items=[];for(const row of $('#rx-items').querySelectorAll('.item-row')){const drug=rx.drugs.find(x=>x.id===Number(row.querySelector('[name=drug]').value)),quantity=Number(row.querySelector('[name=quantity]').value),scaled=quantity*10**(drug?.quantity_scale??0);if(!drug||!Number.isSafeInteger(scaled)||scaled<=0){notify('请核对药品和数量',true);return;}items.push({materialId:drug.id,expectedMaterialRevision:drug.revision,quantityScaled:scaled,directions:row.querySelector('[name=directions]').value});}const button=f.querySelector('button:not([type=button])');button.disabled=true;try{await api('/api/prescriptions',{action:'draft',branchId:rx.branchId,visitId:rx.visitId,patientId:rx.patientId,collectionRoute:'院外',diagnosis:f.elements.diagnosis.value,guidanceNote:f.elements.guidance.value,reason:f.elements.reason.value,items,requestKey:rx.requestKey,commandVersion:1});f.reset();await queryPrescription(rx.visitId,rx.patientId);notify('院外处方草稿已保存');}catch(error){notify(error.message,true);}finally{button.disabled=false;}};
