async function queryPlans(visitId){const branchId=state.branch,[data,options]=await Promise.all([api('/api/plans?'+q({branchId,visitId})),api('/api/plans/options?'+q({branchId}))]);state.plans={branchId,visitId,services:options.services,requestKey:key()};const form=$('#plan-draft'),container=$('#plan-items');form.hidden=!options.services.length;resetItemRows(container);const select=container.querySelector('[name=service]');select.replaceChildren();for(const service of options.services)option(select,service.id,service.name+' / '+service.billing_unit);table($('#plan-list'),[['治疗目标',p=>p.goal],['版本',p=>p.version_no],['状态',p=>p.status],['项目',p=>p.items.map(i=>i.item_description+' × '+i.planned_quantity+'（'+(i.latestDecision||'未决定')+'）').join('；')],['操作',p=>{const box=document.createElement('div');for(const [action,label] of [['publish','已说明方案'],['quote','编制报价'],['decision','记录方案决定']]){if(!p.is_latest||(action==='publish'&&!['草稿','暂缓'].includes(p.status))||(['quote','decision'].includes(action)&&!['待确认','已确认'].includes(p.status)))continue;const b=document.createElement('button');b.className='secondary';b.textContent=label;b.onclick=()=>{if(action==='decision'){openDecision('plan',{plan:p,branchId,visitId});return;}state.planAction={action,plan:p,branchId,visitId,requestKey:key()};const f=$('#plan-action-form');f.reset();dialogError(f,'');$('#plan-action-title').textContent=label;$('#plan-scope-label').hidden=action!=='quote';f.elements.scope.required=action==='quote';$('#plan-action-dialog').showModal();};box.append(b);}return box.childNodes.length?box:'—';}]],data.plans);}
$('#plan-query').onsubmit=async e=>{e.preventDefault();state.plans=null;try{await queryPlans(Number(e.currentTarget.visitId.value));}catch(error){notify(error.message,true);}};
