async function queryQuotes(){const branchId=state.branch,data=await api('/api/quotes?'+q({branchId}));table($('#quote-list'),[['报价编号',x=>x.record_no],['患者',x=>x.patient_name],['版本',x=>x.version_no],['状态',x=>x.status],['项目',x=>x.items.map(i=>i.description_snapshot+' × '+i.quantity+'（'+(i.decision||'未决定')+'）').join('；')],['操作',x=>{const box=document.createElement('div');if(state.role==='cashier'&&x.status==='草稿'&&x.is_latest){const b=document.createElement('button');b.className='secondary';b.textContent='核价出具';b.onclick=()=>{state.quoteIssue={quote:x,branchId,requestKey:key()};const f=$('#quote-issue-form');f.reset();dialogError(f,'');$('#quote-issue-dialog').showModal();};box.append(b);}if(x.is_latest&&x.plan_is_latest&&['已出具','部分接受','已接受'].includes(x.status)){const b=document.createElement('button');b.className='secondary';b.textContent='记录报价决定';b.onclick=()=>openDecision('quote',{quote:x,branchId});box.append(b);}return box.childNodes.length?box:'—';}]],data.quotes);}
$('#quote-issue-form').onsubmit=async e=>{e.preventDefault();const f=e.currentTarget,entry=state.quoteIssue;if(!entry)return;const button=f.querySelector('button:not([type=button])');button.disabled=true;dialogError(f,'');try{const x=entry.quote;await api('/api/quotes',{action:'issue',branchId:entry.branchId,visitId:x.source_visit_id,versionId:x.version_id,expectedRevision:x.revision,expectedQuoteRevision:x.quote_revision,validFrom:f.elements.validFrom.value,validUntil:f.elements.validUntil.value,reason:f.elements.reason.value,requestKey:entry.requestKey,commandVersion:1});$('#quote-issue-dialog').close();state.quoteIssue=null;await queryQuotes();notify('报价已核价出具');}catch(error){dialogError(f,error.message);}finally{button.disabled=false;}};
function resetItemRows(container){for(const row of [...container.querySelectorAll('.item-row')].slice(1))row.remove();}
function addItem(container){const rows=container.querySelectorAll('.item-row');if(rows.length>=20){notify('最多添加 20 项',true);return;}const row=rows[0].cloneNode(true);for(const field of row.querySelectorAll('input,textarea'))field.value='';const remove=document.createElement('button');remove.type='button';remove.className='secondary';remove.textContent='移除此项';remove.onclick=()=>row.remove();row.append(remove);container.append(row);}
$('#add-rx-item').onclick=()=>addItem($('#rx-items'));$('#add-plan-item').onclick=()=>addItem($('#plan-items'));
function openDecision(kind,data){state.decision={kind,...data,requestKey:key()};const f=$('#decision-form');f.reset();dialogError(f,'');f.elements.scope.replaceChildren();option(f.elements.scope,'all','全部项目');const items=kind==='plan'?data.plan.items:data.quote.items;for(const item of items)option(f.elements.scope,item.id,kind==='plan'?item.item_description:item.description_snapshot);f.elements.decision.replaceChildren();option(f.elements.decision,'','请选择');for(const value of kind==='plan'?['同意','暂缓','拒绝','撤回']:['接受','暂缓','拒绝','撤回'])option(f.elements.decision,value,value);$('#decision-title').textContent=kind==='plan'?'记录治疗方案决定':'记录报价决定';$('#decision-dialog').showModal();}
$('#decision-form').onsubmit=async e=>{e.preventDefault();const f=e.currentTarget,entry=state.decision;if(!entry)return;dialogError(f,'');const button=f.querySelector('button:not([type=button])');button.disabled=true;try{if(entry.kind==='plan'){const p=entry.plan;await api('/api/plans',{action:'decide',branchId:entry.branchId,visitId:entry.visitId,versionId:p.version_id,expectedRevision:p.revision,decision:f.elements.decision.value,...(f.elements.scope.value==='all'?{}:{itemId:Number(f.elements.scope.value)}),explanationBasis:f.elements.basis.value,scopeNote:f.elements.scope.value==='all'?'患者对本版全部治疗方案项目的决定':'患者对选定治疗方案项目的决定',requestKey:entry.requestKey,commandVersion:1});}else{const x=entry.quote;await api('/api/quotes',{action:'decide',branchId:entry.branchId,visitId:x.source_visit_id,versionId:x.version_id,expectedRevision:x.revision,expectedQuoteRevision:x.quote_revision,decision:f.elements.decision.value,...(f.elements.scope.value==='all'?{}:{itemId:Number(f.elements.scope.value)}),confirmationBasis:f.elements.basis.value,requestKey:entry.requestKey,commandVersion:1});}$('#decision-dialog').close();state.decision=null;if(entry.kind==='plan')await queryPlans(entry.visitId);else await queryQuotes();notify('患者决定已记录');}catch(error){dialogError(f,error.message);}finally{button.disabled=false;}};
$('#rx-action-form').onsubmit=async e=>{e.preventDefault();const f=e.currentTarget,entry=state.rxAction;if(!entry)return;dialogError(f,'');const button=f.querySelector('button:not([type=button])');button.disabled=true;try{const rx=entry.rx,p=entry.prescription;if(entry.action==='handover'){if(entry.timeInput&&entry.timeInput!==f.elements.handedAt.value)throw Error('时间已修改，请关闭窗口重新查询后办理');entry.timeInput=f.elements.handedAt.value;if(!entry.handedAt)entry.handedAt=new Date(entry.timeInput).toISOString().replace('.000Z','Z');}await api('/api/prescriptions',{action:entry.action,branchId:rx.branchId,visitId:rx.visitId,patientId:rx.patientId,prescriptionId:p.id,expectedRevision:p.revision,confirmed:f.elements.confirmed.checked,reason:f.elements.reason.value,...(entry.action==='handover'?{recipientVerified:f.elements.confirmed.checked,handedOverAt:entry.handedAt}:{medicationNotDispensed:f.elements.confirmed.checked}),requestKey:entry.requestKey,commandVersion:1});$('#rx-action-dialog').close();state.rxAction=null;await queryPrescription(rx.visitId,rx.patientId);notify(entry.action==='handover'?'处方文件交付已记录':'处方已作废');}catch(error){dialogError(f,error.message);}finally{button.disabled=false;}};
function scaledQuantity(value,scale,{signed=false,zero=false}={}){const match=String(value).match(signed?/^(-?)(\d+)(?:\.(\d+))?$/:/^()(\d+)(?:\.(\d+))?$/);if(!match||!Number.isInteger(scale)||scale<0||scale>6||(match[3]||'').length>scale)throw Error('请核对数量及小数位数');const number=Number(match[2])*10**scale+Number((match[3]||'').padEnd(scale,'0')||0),result=match[1]?-number:number;if(!Number.isSafeInteger(result)||(!zero&&result<=0))throw Error('数量超出范围');return result;}
function displayQuantity(value,scale){return String(value/10**scale);}
$('#stock-form').onsubmit=async e=>{e.preventDefault();const f=e.currentTarget,entry=state.stock;if(!entry)return;const b=f.querySelector('button:not([type=button])');b.disabled=true;dialogError(f,'');try{await api('/api/inventory/issue',{stockId:entry.item.stockId,expectedStockRevision:entry.item.revision,branchId:entry.branchId,quantityScaled:scaledQuantity(f.elements.quantity.value,entry.item.scale),reason:f.elements.reason.value,requestKey:entry.requestKey,commandVersion:1});$('#stock-dialog').close();state.stock=null;await load();notify('材料领用已登记');}catch(error){dialogError(f,error.message);}finally{b.disabled=false;}};
async function queryPurchases(){const branchId=state.branch,data=await api('/api/purchases?'+q({branchId}));state.purchaseData={...data,branchId,requestKey:key()};const form=$('#purchase-create');form.hidden=state.role!=='assistant'||!data.suppliers.length||!data.materials.length;$('#purchase-empty').hidden=state.role!=='assistant'||!!(data.suppliers.length&&data.materials.length);for(const [field,items] of [['supplier',data.suppliers],['material',data.materials]]){const select=form.elements[field];select.replaceChildren();for(const x of items)option(select,x.id,x.name);}if(!form.hidden&&!form.elements.agreedAt.value)form.elements.agreedAt.value=localTime((await api('/api/status')).businessTime);
 table($('#purchase-list'),[['采购编号',x=>x.record_no],['供应商',x=>data.suppliers.find(s=>s.id===x.supplier_id)?.name||x.supplier_id],['状态',x=>x.status],['项目',x=>x.items.map(i=>{const m=data.materials.find(y=>y.id===i.material_id);return (m?.name||i.material_id)+' × '+displayQuantity(i.ordered_quantity_scaled,m?.quantity_scale||0);}).join('；')],['操作',x=>{const action=state.role==='manager'&&x.status==='待确认'?'approve':state.role==='assistant'&&x.status==='已确认'?'receive':null;if(!action)return '—';const b=document.createElement('button');b.className='secondary';b.textContent=action==='approve'?'确认采购':'登记到货';b.onclick=async()=>{try{state.purchaseAction={action,order:x,data:state.purchaseData,requestKey:key()};const f=$('#purchase-action-form');f.reset();dialogError(f,'');$('#purchase-action-title').textContent=b.textContent;$('#purchase-receive-fields').hidden=action!=='receive';for(const field of ['item','batch','location','arrivedAt','quantity','evidence'])f.elements.namedItem(field).required=action==='receive';if(action==='receive'){const item=f.elements.namedItem('item'),location=f.elements.location;item.replaceChildren();location.replaceChildren();for(const line of x.items.filter(i=>!['剩余已取消','履行已完成'].includes(i.status))){const m=data.materials.find(y=>y.id===line.material_id);if(m)option(item,line.id,m.name);}for(const loc of data.locations)option(location,loc.id,loc.name);const update=()=>{const selected=x.items.find(i=>i.id===Number(item.value)),batch=f.elements.batch;batch.replaceChildren();for(const v of data.batches.filter(z=>z.material_id===selected?.material_id))option(batch,v.id,v.batch_no);};item.onchange=update;update();f.elements.arrivedAt.value=localTime((await api('/api/status')).businessTime);}$('#purchase-action-dialog').showModal();}catch(error){notify(error.message,true);}};return b;}]],data.orders);$('#batch-panel').hidden=state.role!=='manager';if(state.role==='manager')table($('#batch-list'),[['批次',x=>x.batch_no],['材料',x=>data.materials.find(m=>m.id===x.material_id)?.name||x.material_id],['状态',x=>x.status],['操作',x=>{if(x.status!=='待检')return '—';const button=document.createElement('button');button.className='secondary';button.textContent='核实放行';button.onclick=()=>{state.purchaseAction={action:'release',batch:x,data:state.purchaseData,requestKey:key()};const f=$('#purchase-action-form');f.reset();dialogError(f,'');$('#purchase-action-title').textContent='核实放行批次';$('#purchase-receive-fields').hidden=true;for(const field of ['item','batch','location','arrivedAt','quantity','evidence'])f.elements.namedItem(field).required=false;$('#purchase-action-dialog').showModal();};return button;}]],data.batches);}
$('#purchase-create').onsubmit=async e=>{e.preventDefault();const f=e.currentTarget,data=state.purchaseData;if(!data)return;const supplier=data.suppliers.find(x=>x.id===Number(f.elements.supplier.value)),material=data.materials.find(x=>x.id===Number(f.elements.material.value));if(!supplier||!material){notify('请选择有效供应商和材料',true);return;}const b=f.querySelector('button');b.disabled=true;try{await api('/api/purchases',{action:'create',branchId:data.branchId,supplierId:supplier.id,expectedSupplierRevision:supplier.revision,items:[{materialId:material.id,expectedMaterialRevision:material.revision,quantityScaled:scaledQuantity(f.elements.quantity.value,material.quantity_scale),unitPriceCents:scaledQuantity(f.elements.price.value,2,{zero:true})}],agreedAt:new Date(f.elements.agreedAt.value).toISOString().replace('.000Z','Z'),deliveryTerms:f.elements.terms.value,reason:f.elements.reason.value,requestKey:data.requestKey,commandVersion:1});f.reset();await queryPurchases();notify('采购单已提交负责人确认');}catch(error){notify(error.message,true);}finally{b.disabled=false;}};
