async function loadTransfers(){const branchId=state.branch,[data,options,clock]=await Promise.all([api('/api/transfer-proposals?'+q({branchId})),api('/api/reception/options?'+q({branchId})),api('/api/status')]);state.transferData={...data,options,branchId,requestKey:key()};const f=$('#transfer-create');f.elements.appointment.replaceChildren();f.elements.target.replaceChildren();for(const a of options.appointments.filter(x=>x.status==='已预约'))option(f.elements.appointment,a.id,a.patient_name+' / '+time(a.planned_start));for(const b of data.branches)option(f.elements.target,b.id,b.name);if(!f.elements.contactedAt.value)f.elements.contactedAt.value=localTimeSeconds(clock.businessTime);table($('#transfer-list'),[['患者',x=>x.patientName],['来源门店',x=>x.sourceBranchId],['目标门店',x=>x.targetBranchId],['状态',x=>x.status],['申请依据',x=>x.reason],['操作',x=>{const box=document.createElement('div');if(x.status==='待目标店确认'||x.status==='原预约已变化'&&x.sourceBranchId===branchId){const actions=x.sourceBranchId===branchId?[['withdraw','撤回申请']]:[['accept','确认新预约'],['reject','拒绝申请']];for(const [action,label] of actions){const b=document.createElement('button');b.className='secondary';b.textContent=label;b.onclick=()=>openTransferAction(action,x,state.transferData);box.append(b);}}return box.childNodes.length?box:'—';}]],data.items);}
$('#transfer-create').onsubmit=async e=>{e.preventDefault();const f=e.currentTarget,data=state.transferData;if(!data)return;const a=data.options.appointments.find(x=>x.id===Number(f.elements.appointment.value)),b=f.querySelector('button');if(!a){notify('请选择本店有效预约',true);return;}b.disabled=true;try{await api('/api/transfer-proposals',{action:'propose',branchId:data.branchId,targetBranchId:Number(f.elements.target.value),appointmentId:a.id,expectedRevision:a.revision,patientConfirmed:f.elements.confirmed.checked,method:f.elements.method.value,contactedAt:new Date(f.elements.contactedAt.value).toISOString().replace('.000Z','Z'),contactNote:f.elements.note.value,reason:f.elements.reason.value,requestKey:data.requestKey,commandVersion:1});f.reset();await loadTransfers();notify('交接申请已发出，原预约仍有效');}catch(error){notify(error.message,true);}finally{b.disabled=false;}};
async function openTransferAction(action,item,data){try{const f=$('#transfer-form');f.reset();dialogError(f,'');state.transferAction={action,item,data,requestKey:key()};$('#transfer-title').textContent={accept:'确认目标店预约',reject:'拒绝交接申请',withdraw:'撤回交接申请'}[action];$('#transfer-summary').textContent=item.patientName+' / '+item.patientNo;const accepting=action==='accept';$('#transfer-accept-fields').hidden=!accepting;for(const name of ['schedule','startsAt','endsAt','method','contactedAt','note','confirmed'])f.elements[name].required=accepting;if(accepting){f.elements.schedule.replaceChildren();for(const s of data.options.schedules)option(f.elements.schedule,s.id,s.dentist_name+' / '+s.chair_name+' / '+time(s.starts_at));f.elements.contactedAt.value=localTimeSeconds((await api('/api/status')).businessTime);}$('#transfer-dialog').showModal();}catch(error){notify(error.message,true);}}
$('#transfer-form').onsubmit=async e=>{e.preventDefault();const f=e.currentTarget,entry=state.transferAction;if(!entry)return;const b=f.querySelector('button:not([type=button])');b.disabled=true;dialogError(f,'');try{const p=entry.item,data=entry.data,base={requestKey:entry.requestKey,commandVersion:1,reason:f.elements.reason.value};if(entry.action==='accept'){const schedule=data.options.schedules.find(s=>s.id===Number(f.elements.schedule.value));if(!schedule)throw Error('请选择目标店有效排班');await api('/api/reception',{...base,action:'transfer',branchId:p.sourceBranchId,targetBranchId:p.targetBranchId,transferProposalId:p.id,appointmentId:p.appointmentId,expectedRevision:p.appointmentRevision,patientConfirmed:f.elements.confirmed.checked,scheduleId:schedule.id,scheduleRevision:schedule.revision,startsAt:new Date(f.elements.startsAt.value).toISOString().replace('.000Z','Z'),endsAt:new Date(f.elements.endsAt.value).toISOString().replace('.000Z','Z'),equipmentIds:[],transferContact:{method:f.elements.method.value,note:f.elements.note.value,contactedAt:new Date(f.elements.contactedAt.value).toISOString().replace('.000Z','Z')}});}else await api('/api/transfer-proposals',{...base,action:entry.action,branchId:data.branchId,proposalId:p.id});$('#transfer-dialog').close();state.transferAction=null;await loadTransfers();notify(entry.action==='accept'?'目标店预约已确认，原预约已取消':'交接申请已处理');}catch(error){dialogError(f,error.message);}finally{b.disabled=false;}};
function updateApprovalDentists(){const data=state.approvalData,f=$('#approval-create');f.elements.dentist.replaceChildren();if(!data)return;for(const p of data.options.dentists.filter(x=>x.branch_id===Number(f.elements.target.value)))option(f.elements.dentist,p.id,p.name);}
$('#approval-create [name=target]').onchange=updateApprovalDentists;
function openApprovalAction(action,item,branchId){state.approvalAction={action,item,branchId,requestKey:key()};const f=$('#approval-form');f.reset();dialogError(f,'');$('#approval-title').textContent={approve:'确认跨店授权',reject:'拒绝授权申请',withdraw:'撤回授权申请',revoke:'撤销跨店授权'}[action];$('#approval-dialog').showModal();}
async function loadApprovals(){const branchId=state.branch,[data,options,clock]=await Promise.all([api('/api/approvals?'+q({branchId})),api('/api/approvals/options?'+q({branchId})),api('/api/status')]);state.approvalData={...data,options,branchId,requestKey:key()};const f=$('#approval-create');f.elements.visit.replaceChildren();f.elements.target.replaceChildren();for(const v of options.visits)option(f.elements.visit,v.id,v.patient_name+' / '+v.record_no);for(const b of options.branches)option(f.elements.target,b.id,b.name);updateApprovalDentists();table($('#approval-list'),[['患者编号',x=>x.patientId],['来源门店',x=>x.sourceBranchId],['目标门店',x=>x.targetBranchId],['目标牙医',x=>x.dentistId],['范围',x=>x.scope],['截止',x=>time(x.validUntil)],['状态',x=>x.status],['操作',x=>{const box=document.createElement('div');if(x.status==='待确认'){const actions=x.sourceBranchId===branchId?[['withdraw','撤回申请']]:[['approve','确认授权'],['reject','拒绝申请']];for(const [action,label] of actions){const b=document.createElement('button');b.className='secondary';b.textContent=label;b.onclick=()=>openApprovalAction(action,x,branchId);box.append(b);}}return box.childNodes.length?box:'—';}]],data.items);table($('#grant-list'),[['患者',x=>x.patient_name],['来源门店',x=>x.source_branch_id],['目标门店',x=>x.target_branch_id],['牙医',x=>x.dentist_name],['范围',x=>x.scope],['截止',x=>time(x.valid_until)],['状态',x=>x.revoked_at?'已撤销':x.valid_until&&x.valid_until<=clock.businessTime?'已过期':'已授权'],['操作',x=>{if(!x.can_revoke)return '—';const b=document.createElement('button');b.className='secondary';b.textContent='撤销授权';b.onclick=()=>openApprovalAction('revoke',x,branchId);return b;}]],options.grants);}
$('#approval-create').onsubmit=async e=>{e.preventDefault();const f=e.currentTarget,data=state.approvalData;if(!data)return;const visit=data.options.visits.find(x=>x.id===Number(f.elements.visit.value)),b=f.querySelector('button');if(!visit){notify('请选择本店来源就诊',true);return;}b.disabled=true;try{await api('/api/approvals',{action:'propose',sourceBranchId:data.branchId,targetBranchId:Number(f.elements.target.value),dentistId:Number(f.elements.dentist.value),patientId:visit.patient_id,visitId:visit.id,scope:f.elements.scope.value,validUntil:new Date(f.elements.validUntil.value).toISOString().replace('.000Z','Z'),reason:f.elements.reason.value,requestKey:data.requestKey,commandVersion:1});f.reset();await loadApprovals();notify('跨店查阅申请已提交');}catch(error){notify(error.message,true);}finally{b.disabled=false;}};
$('#approval-form').onsubmit=async e=>{e.preventDefault();const f=e.currentTarget,entry=state.approvalAction;if(!entry)return;const b=f.querySelector('button:not([type=button])');b.disabled=true;dialogError(f,'');try{const data={action:entry.action,reason:f.elements.reason.value,requestKey:entry.requestKey,commandVersion:1};if(entry.action==='revoke')await api('/api/grants',{...data,grantId:entry.item.id});else await api('/api/approvals',{...data,proposalId:entry.item.id});$('#approval-dialog').close();state.approvalAction=null;await loadApprovals();notify(entry.action==='revoke'?'授权已撤销':'授权申请已处理');}catch(error){dialogError(f,error.message);}finally{b.disabled=false;}};
async function loadCrossClinical(){const branchId=state.branch,d=await api('/api/clinical/grants?'+q({branchId}));$('#crossclinical-result').replaceChildren();table($('#crossclinical-list'),[['患者',x=>x.patient_name],['来源门店',x=>x.source_name],['就诊编号',x=>x.visit_no],['范围',x=>x.scope==='record'?'病历':'健康资料'],['截止',x=>time(x.valid_until)],['操作',x=>{const b=document.createElement('button');b.className='secondary';b.textContent='查看资料';b.onclick=async()=>{try{const result=await api('/api/clinical',{targetBranchId:branchId,sourceBranchId:x.source_branch_id,patientId:x.patient_id,visitId:x.visit_id,scope:x.scope}),box=$('#crossclinical-result'),dl=document.createElement('dl');dl.className='details';const fields=x.scope==='record'?[['主诉',result.record.chief_complaint],['诊断',result.record.diagnosis],['诊疗建议',result.record.treatment_advice],['检查所见',result.findings.map(i=>i.finding_text).join('；')]]:[['健康资料',result.versions.flatMap(v=>v.items.map(i=>i.category+'：'+i.certainty+'，'+i.content)).join('；')]];for(const [name,value] of fields){const dt=document.createElement('dt'),dd=document.createElement('dd');dt.textContent=name;dd.textContent=value||'未填写';dl.append(dt,dd);}box.replaceChildren(dl);}catch(error){notify(error.message,true);}};return b;}]],d.items);}

async function loadFeeRequests(){
 const branchId=state.branch,data=await api('/api/fee-requests?'+q({branchId}));
 const sources=[];for(const account of data.accounts)for(const bill of account.bills)for(const item of bill.items)for(const use of bill.uses)if(item.remaining_cents>0&&use.remaining_cents>0)sources.push({account,bill,item,use});
 table($('#fee-sources'),[['患者',x=>x.account.name],['账单',x=>x.bill.record_no],['诊疗项目',x=>x.item.name],['原收款',x=>x.use.record_no],['可申请上限',x=>'¥ '+(Math.min(x.item.remaining_cents,x.use.remaining_cents)/100).toFixed(2)],['操作',x=>{if(state.role!=='cashier')return '—';const b=document.createElement('button');b.className='secondary';b.textContent='申请更正退费';b.onclick=()=>feeAdjustment(x,branchId);return b;}]],sources);
 table($('#fee-requests-list'),[['申请编号',x=>x.record_no],['患者',x=>x.patient_name],['账单/项目',x=>[x.bill_no,x.item_name].filter(Boolean).join(' / ')||'预付款'],['申请金额',x=>'¥ '+(x.proposed_refund_cents/100).toFixed(2)],['状态',x=>x.refunds.some(r=>r.status==='已确认退款')?'已登记退款':x.status],['操作',x=>{const box=document.createElement('div');const actions=state.role==='manager'&&x.status==='待审核'?[['approve','同意'],['reject','拒绝']]:state.role==='cashier'&&x.status==='已同意'&&!x.refunds.length?[['refund','登记退款']]:[];for(const [action,label] of actions){const b=document.createElement('button');b.className='secondary';b.textContent=label;b.onclick=()=>feeAction(action,x,data.accounts,branchId);box.append(b);}return box.childNodes.length?box:'—';}]],data.requests);
}
async function feeAdjustment(x,branchId){const raw=prompt('请输入申请金额（元）');if(raw===null)return;let amountCents;try{amountCents=scaledQuantity(raw,2,{zero:false});}catch(e){notify(e.message,true);return;}const reason=prompt('请输入费用更正原因');if(!reason?.trim())return;const evidence=prompt('请输入核对依据');if(!evidence?.trim())return;try{await api('/api/fee-requests',{action:'requestAdjustment',branchId,patientId:x.account.patient_id,expectedFundsRevision:x.account.revision,paymentId:x.use.patient_payment_id,expectedPaymentRevision:x.use.payment_revision,billId:x.bill.id,expectedBillRevision:x.bill.revision,billItemId:x.item.id,expectedItemRevision:x.item.revision,kind:x.use.kind,allocationId:x.use.id,expectedAllocationRevision:x.use.revision,amountCents,reason,evidence,requestKey:key(),commandVersion:1});await loadFeeRequests();notify('费用更正退费申请已提交');}catch(e){notify(e.message,true);}}
async function feeAction(action,request,accounts,branchId){const account=accounts.find(a=>a.patient_id===request.patient_id);if(!account){notify('患者资金账户不可用',true);return;}const input={action,branchId,patientId:request.patient_id,requestId:request.id,expectedRevision:request.revision,expectedFundsRevision:account.revision,requestKey:key(),commandVersion:1};if(action==='refund'){if(!confirm('请确认退款已在系统外实际完成。系统不会发起退款。'))return;input.confirmed=true;input.recipientVerification=prompt('请输入退款接收方核实依据');if(!input.recipientVerification?.trim())return;input.evidence=prompt('请输入退款结果依据');if(!input.evidence?.trim())return;if(request.channel!=='现金'){input.externalReference=prompt('请输入退款交易号');if(!input.externalReference?.trim())return;}}else{input.reviewNote=prompt('请输入审核意见');if(!input.reviewNote?.trim())return;}try{await api('/api/fee-requests',input);await loadFeeRequests();notify(action==='refund'?'系统外退款已登记':'审核结果已保存');}catch(e){notify(e.message,true);}}
